head.script:

scwin.onpageload = function() {
ipt_cal1.setValue("20220101000000");
};

	scwin.checkVal = function() {
		var str = WebSquare.wUnit.getDomById('ipt_cal1_calendar_selectbox_year').innerText
		var searchStr = '1978년';
		return str.includes(searchStr) == false;
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('ipt_cal1_img').click()");
		WebSquare.wUnit.addCommand("pause", "400");

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
